 static void MapOperations(RouteGroupBuilder t){
 t.MapGet("/budgets",async(Guid tenant,Guid? entity,Guid? workspace,AppDb db,FinanceService s)=>{var q=s.Scoped<FinanceBudget>(tenant,entity:entity,workspace:workspace);return await q.OrderByDescending(b=>b.Id).Take(200).Select(b=>new{b.Id,b.EntityId,b.UnitId,b.PeriodId,b.EventId,b.CommitteeId,b.Name,b.Currency,b.Lines,b.Amount,b.Status,b.Revision,b.AuthorId,b.ApprovedBy,committed=db.Set<FinanceExpense>().Where(e=>e.BudgetId==b.Id&&e.Status=="Pending Approval").Sum(e=>e.Amount),actual=db.Set<FinanceExpense>().Where(e=>e.BudgetId==b.Id&&(e.Status=="Approved"||e.Status=="Paid")).Sum(e=>e.Amount)}).ToListAsync();});
 t.MapPost("/budgets",async(Guid tenant,FinanceBudget r,AppDb db,Access a,FinanceService s)=>{var entity=await s.Require(tenant,r.EntityId,r.UnitId,"finance.budget");FinanceService.Money(r.Amount,entity.Currency);if(r.Name.Length is <3 or >160||!await db.Set<AccountingPeriod>().AnyAsync(p=>p.TenantId==tenant&&p.EntityId==entity.Id&&p.Id==r.PeriodId&&!p.Closed))throw new DomainException("Choose an open fiscal period and budget name");var lines=JsonSerializer.Deserialize<BudgetInput[]>(r.Lines,CommunicationService.JsonOptions)??[];if(lines.Length is <1 or >100||lines.Sum(l=>l.Amount)!=r.Amount)throw new DomainException("Budget lines must sum to the approved request amount");foreach(var line in lines){FinanceService.Money(line.Amount,entity.Currency);if(!await db.Set<LedgerAccount>().AnyAsync(x=>x.TenantId==tenant&&x.EntityId==entity.Id&&x.Code==line.AccountCode&&x.Type=="Expense"&&x.Active))throw new DomainException("Budget categories need active expense accounts");}await ValidateFinanceLinks(tenant,r.UnitId,r.EventId,r.CommitteeId,db,a);var budget=new FinanceBudget{TenantId=tenant,EntityId=entity.Id,UnitId=r.UnitId,PeriodId=r.PeriodId,EventId=r.EventId,CommitteeId=r.CommitteeId,Name=r.Name,Currency=entity.Currency,Amount=r.Amount,Lines=r.Lines,Status="Pending Approval",AuthorId=a.UserId};db.Add(budget);db.Add(new BudgetRevision{TenantId=tenant,EntityId=entity.Id,UnitId=r.UnitId,BudgetId=budget.Id,Revision=0,Snapshot=JsonSerializer.Serialize(budget),AuthorId=a.UserId});a.Audit(tenant,"finance.budget.requested",budget.Id);await db.SaveChangesAsync();return Results.Ok(budget);});
 t.MapPost("/budgets/{id:guid}/revision",async(Guid tenant,Guid id,BudgetChange r,AppDb db,Access a,FinanceService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var budget=await db.Set<FinanceBudget>().SingleOrDefaultAsync(b=>b.TenantId==tenant&&b.Id==id)??throw new AccessDeniedException();await s.Require(tenant,budget.EntityId,budget.UnitId,"finance.budget");if(budget.Revision!=r.Revision||budget.Status!="Approved"||r.Reason.Length is <3 or >1000)throw new DomainException("Choose a current approved budget and explain its revision");FinanceService.Money(r.Amount,budget.Currency);var lines=JsonSerializer.Deserialize<BudgetInput[]>(r.Lines,CommunicationService.JsonOptions)??[];if(lines.Sum(l=>l.Amount)!=r.Amount||lines.Length is <1 or >100)throw new DomainException("Budget line total does not match");var spent=await db.Set<FinanceExpense>().Where(e=>e.BudgetId==id&&new[]{"Approved","Paid","Pending Approval"}.Contains(e.Status)).SumAsync(e=>e.Amount);if(r.Amount<spent)throw new DomainException("Revised budget cannot be below actuals and commitments");budget.Revision++;budget.Amount=r.Amount;budget.Lines=r.Lines;budget.AuthorId=a.UserId;budget.ApprovedBy=null;budget.Status="Pending Approval";db.Add(new BudgetRevision{TenantId=tenant,EntityId=budget.EntityId,UnitId=budget.UnitId,BudgetId=id,Revision=budget.Revision,Snapshot=JsonSerializer.Serialize(new{budget.Amount,budget.Lines,r.Reason}),AuthorId=a.UserId});await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(budget);});
 t.MapGet("/budgets/{id:guid}/history",async(Guid tenant,Guid id,AppDb db,FinanceService s)=>{var b=await db.Set<FinanceBudget>().SingleOrDefaultAsync(b=>b.TenantId==tenant&&b.Id==id)??throw new AccessDeniedException();await s.Require(tenant,b.EntityId,b.UnitId);return await db.Set<BudgetRevision>().Where(v=>v.TenantId==tenant&&v.BudgetId==id).OrderBy(v=>v.Revision).ToListAsync();});
 t.MapPost("/budgets/{id:guid}/decision",async(Guid tenant,Guid id,FinanceDecision r,AppDb db,Access a,FinanceService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var b=await db.Set<FinanceBudget>().SingleOrDefaultAsync(b=>b.TenantId==tenant&&b.Id==id&&b.Status=="Pending Approval")??throw new AccessDeniedException();var e=await s.Require(tenant,b.EntityId,b.UnitId,"finance.approve");if(b.Revision!=r.Revision)throw new DomainException("Refresh budget revision");await s.Review(tenant,id,b.AuthorId,b.UnitId!.Value,"FinanceBudget",r,b.Amount,e);b.Status=r.Decision=="Approve"?"Approved":"Rejected";b.ApprovedBy=r.Decision=="Approve"?a.UserId:null;await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(b);});
 t.MapGet("/expenses/{id:guid}",async(Guid tenant,Guid id,AppDb db,Access a,FinanceService service)=>{var expense=await db.Set<FinanceExpense>().SingleOrDefaultAsync(x=>x.TenantId==tenant&&x.Id==id)??throw new AccessDeniedException();await service.Require(tenant,expense.EntityId,expense.UnitId);if(!await a.Can(tenant,"finance.expense",expense.UnitId)&&!await a.Can(tenant,"finance.approve",expense.UnitId))throw new AccessDeniedException();return Results.Ok(new{expense,files=await db.Set<FinanceFile>().Where(f=>f.TenantId==tenant&&f.ResourceId==id&&f.Kind=="Expense").Select(f=>new{f.Id,f.Name,f.ContentType}).ToListAsync(),decisions=await db.Set<CommunityDecision>().Where(d=>d.TenantId==tenant&&d.ResourceId==id).OrderBy(d=>d.At).ToListAsync()});});
 t.MapGet("/expenses",async(Guid tenant,Guid? entity,Guid? workspace,string? status,int? page,FinanceService s)=>{var q=s.Scoped<FinanceExpense>(tenant,entity:entity,workspace:workspace);if(status!=null)q=q.Where(e=>e.Status==status);return Results.Ok(new{total=await q.CountAsync(),items=await q.OrderByDescending(e=>e.Date).Skip(Page(page)*50).Take(50).ToListAsync()});});
 t.MapPost("/expenses",async(Guid tenant,FinanceExpense r,AppDb db,Access a,FinanceService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var e=await s.Require(tenant,r.EntityId,r.UnitId,"finance.expense");FinanceService.Money(r.Amount,e.Currency);if(r.Vendor.Length is <1 or >200||r.Description.Length is <3 or >2000||!await db.Set<LedgerAccount>().AnyAsync(x=>x.TenantId==tenant&&x.EntityId==e.Id&&x.Code==r.AccountCode&&x.Active&&x.Type=="Expense"))throw new DomainException("Enter vendor, description and active expense category");await ValidateFinanceLinks(tenant,r.UnitId,r.EventId,r.CommitteeId,db,a);if(r.BudgetId!=null){var budget=await db.Set<FinanceBudget>().SingleOrDefaultAsync(b=>b.TenantId==tenant&&b.EntityId==e.Id&&b.UnitId==r.UnitId&&b.Id==r.BudgetId&&b.Status=="Approved")??throw new DomainException("Choose an approved budget in this entity and organization");var period=await db.Set<AccountingPeriod>().SingleAsync(p=>p.Id==budget.PeriodId);if(r.Date<period.StartsOn||r.Date>period.EndsOn||budget.EventId!=r.EventId||budget.CommitteeId!=r.CommitteeId)throw new DomainException("Expense date/event/committee must match its budget");var rows=JsonSerializer.Deserialize<BudgetInput[]>(budget.Lines,CommunicationService.JsonOptions)!;var cap=rows.Where(l=>l.AccountCode==r.AccountCode).Sum(l=>l.Amount);var used=await db.Set<FinanceExpense>().Where(x=>x.BudgetId==budget.Id&&x.AccountCode==r.AccountCode&&new[]{"Pending Approval","Approved","Paid"}.Contains(x.Status)).SumAsync(x=>x.Amount);if(used+r.Amount>cap)throw new DomainException("Expense exceeds available category budget including commitments");}var expense=new FinanceExpense{TenantId=tenant,EntityId=e.Id,UnitId=r.UnitId,AuthorId=a.UserId,BudgetId=r.BudgetId,EventId=r.EventId,CommitteeId=r.CommitteeId,Vendor=r.Vendor,Description=r.Description,AccountCode=r.AccountCode,Amount=r.Amount,Currency=e.Currency,Date=r.Date};db.Add(expense);a.Audit(tenant,"finance.expense.requested",expense.Id);await FinanceCommunication.Approval(expense,a.UserId,"Expense approval requested",db);await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(expense);});
 t.MapPost("/expenses/{id:guid}/decision",async(Guid tenant,Guid id,FinanceDecision r,AppDb db,Access a,FinanceService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var x=await db.Set<FinanceExpense>().SingleOrDefaultAsync(x=>x.TenantId==tenant&&x.Id==id&&x.Status=="Pending Approval")??throw new AccessDeniedException();var e=await s.Require(tenant,x.EntityId,x.UnitId,"finance.approve");await s.Review(tenant,id,x.AuthorId,x.UnitId!.Value,"FinanceExpense",r,x.Amount,e);if(r.Decision=="Approve"){var journal=await s.Post(e,x.UnitId.Value,x.Date,x.Description,"Expense",id,"expense:"+id,[new(x.AccountCode,x.Amount,0),new("2000",0,x.Amount)],x.AuthorId,a.UserId);x.Status="Approved";x.ApprovedBy=a.UserId;x.JournalId=journal.Id;}else x.Status="Rejected";await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(x);});
 t.MapPost("/expenses/{id:guid}/pay",async(Guid tenant,Guid id,ExpensePay r,AppDb db,Access a,FinanceService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var x=await db.Set<FinanceExpense>().SingleOrDefaultAsync(x=>x.TenantId==tenant&&x.Id==id&&x.Status=="Approved")??throw new AccessDeniedException();var e=await s.Require(tenant,x.EntityId,x.UnitId,"finance.collect");if(r.Reference.Length is <3 or >160||r.Method is not("Cash" or "Bank transfer"))throw new DomainException("Enter an actual payment reference and cash/bank method");var code=r.Method=="Cash"?"1000":"1010";if(r.BankId!=null){var bank=await db.Set<FinanceBank>().SingleOrDefaultAsync(b=>b.TenantId==tenant&&b.EntityId==e.Id&&b.Id==r.BankId&&b.Active)??throw new AccessDeniedException();await s.Require(tenant,e.Id,bank.UnitId,"finance.bank");code=bank.AccountCode;}var j=await s.Post(e,x.UnitId!.Value,r.Date,"Expense payment "+r.Reference,"ExpensePayment",id,"expense-payment:"+id,[new("2000",x.Amount,0),new(code,0,x.Amount)],a.UserId,x.ApprovedBy);x.Status="Paid";x.PaymentJournalId=j.Id;x.PaymentReference=r.Reference;x.BankId=r.BankId;a.Audit(tenant,"finance.expense.paid",id);await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(x);});
 t.MapGet("/banks",async(Guid tenant,Guid? entity,FinanceService s)=>await s.Scoped<FinanceBank>(tenant,"finance.bank",entity).OrderBy(b=>b.Name).Select(b=>new{b.Id,b.EntityId,b.UnitId,b.Name,b.LastFour,b.Currency,b.AccountCode,b.Active}).ToListAsync());
 t.MapPost("/banks",async(Guid tenant,BankWrite r,AppDb db,Access a,FinanceService s,FinanceGateway provider)=>{var e=await s.Require(tenant,r.EntityId,r.UnitId,"finance.bank");if(r.Name.Length is <2 or >160||r.Details.Length is <4 or >4000||!await db.Set<LedgerAccount>().AnyAsync(x=>x.TenantId==tenant&&x.EntityId==e.Id&&x.Code==r.AccountCode&&x.Type=="Asset"&&x.Active&&!x.Control))throw new DomainException("Choose an active asset account and restricted bank details");var bank=new FinanceBank{TenantId=tenant,EntityId=e.Id,UnitId=r.UnitId,Name=r.Name,LastFour=new string(r.Details.Where(char.IsLetterOrDigit).TakeLast(4).ToArray()),ProtectedDetails=provider.Protect(r.Details),Currency=e.Currency,AccountCode=r.AccountCode};db.Add(bank);a.Audit(tenant,"finance.bank.created",bank.Id);await db.SaveChangesAsync();return Results.Ok(new{bank.Id,bank.Name,bank.LastFour});});
 t.MapGet("/bank-transactions",async(Guid tenant,Guid? entity,Guid? bank,string? status,int? page,FinanceService s)=>{var q=s.Scoped<BankTransaction>(tenant,"finance.reconcile",entity);if(bank!=null)q=q.Where(x=>x.BankId==bank);if(status!=null)q=q.Where(x=>x.Status==status);return Results.Ok(new{total=await q.CountAsync(),items=await q.OrderByDescending(x=>x.Date).Skip(Page(page)*50).Take(50).ToListAsync()});});
 t.MapPost("/banks/{id:guid}/import",async(Guid tenant,Guid id,BankImport r,AppDb db,Access a,FinanceService s)=>{var bank=await db.Set<FinanceBank>().SingleOrDefaultAsync(b=>b.TenantId==tenant&&b.Id==id&&b.Active)??throw new AccessDeniedException();await s.Require(tenant,bank.EntityId,bank.UnitId,"finance.reconcile");if(r.Rows.Length is <1 or >10000||r.Key.Length is <3 or >100)throw new DomainException("Import 1–10,000 rows with a stable batch key");foreach(var row in r.Rows){FinanceService.Money(Math.Abs(row.Amount),bank.Currency);if(row.Reference.Length is <1 or >160||row.Description.Length>1000)throw new DomainException("Every bank row needs date, amount and bounded reference");}var prior=await db.Set<FinanceJob>().SingleOrDefaultAsync(j=>j.TenantId==tenant&&j.EntityId==bank.EntityId&&j.Key=="bank:"+r.Key);if(prior!=null)return Results.Ok(prior);var job=new FinanceJob{TenantId=tenant,EntityId=bank.EntityId,UnitId=bank.UnitId,Kind="BankImport",AuthorId=a.UserId,Key="bank:"+r.Key,Payload=JsonSerializer.Serialize(new{bankId=id,rows=r.Rows})};db.Add(job);a.Audit(tenant,"finance.bank.imported",job.Id,new{rows=r.Rows.Length});await db.SaveChangesAsync();return Results.Ok(job);});
 t.MapPost("/bank-transactions/{id:guid}/match",async(Guid tenant,Guid id,ReconcileWrite r,AppDb db,Access a,FinanceService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var row=await db.Set<BankTransaction>().SingleOrDefaultAsync(x=>x.TenantId==tenant&&x.Id==id&&x.Status=="Unmatched")??throw new AccessDeniedException();var e=await s.Require(tenant,row.EntityId,row.UnitId,"finance.reconcile");var payment=await db.Set<FinancePayment>().SingleOrDefaultAsync(p=>p.TenantId==tenant&&p.EntityId==row.EntityId&&p.Id==r.PaymentId&&p.Status=="Confirmed")??throw new DomainException("Match a confirmed payment in the same entity");await s.Require(tenant,payment.EntityId,payment.UnitId,"finance.reconcile");var matched=await db.Set<ReconciliationMatch>().Where(m=>m.PaymentId==payment.Id).SumAsync(m=>m.Amount);if(row.Amount<=0||row.Currency!=payment.Currency||row.Amount>payment.Amount-matched||payment.BankId!=null&&payment.BankId!=row.BankId)throw new DomainException("Bank credit currency/account/amount does not match available payment settlement");var match=new ReconciliationMatch{TenantId=tenant,EntityId=e.Id,UnitId=row.UnitId,BankTransactionId=id,PaymentId=payment.Id,Amount=row.Amount,AuthorId=a.UserId};db.Add(match);row.Status="Matched";row.PaymentId=payment.Id;if(matched+row.Amount==payment.Amount)payment.SettledOn=row.Date;if(payment.ProviderId!=null){var bank=await db.Set<FinanceBank>().SingleAsync(b=>b.Id==row.BankId);await s.Post(e,payment.UnitId!.Value,row.Date,"Gateway settlement "+row.Reference,"GatewaySettlement",id,"gateway-settlement:"+id,[new(bank.AccountCode,row.Amount,0),new("1020",0,row.Amount)],a.UserId,null,payment.MembershipId,payment.PayerUnitId);}a.Audit(tenant,"finance.reconciliation.matched",id);await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(match);});
 t.MapGet("/donors",async(Guid tenant,Guid? entity,FinanceService s)=>await s.Scoped<FinanceDonor>(tenant,"finance.collect",entity).OrderBy(d=>d.Name).Take(200).ToListAsync());
 t.MapPost("/donors",async(Guid tenant,FinanceDonor r,AppDb db,Access a,FinanceService s)=>{await s.Require(tenant,r.EntityId,r.UnitId,"finance.collect");if(r.Name.Length is <2 or >200||r.Contact.Length>500||r.Notes.Length>2000)throw new DomainException("Check contributor name and contact details");if(r.PersonId!=null&&!await db.Memberships.AnyAsync(m=>m.TenantId==tenant&&m.PersonId==r.PersonId&&m.ChapterId==r.UnitId))throw new AccessDeniedException();var donor=new FinanceDonor{TenantId=tenant,EntityId=r.EntityId,UnitId=r.UnitId,Name=r.Name,Kind=r.Kind,Contact=r.Contact,Notes=r.Notes,PersonId=r.PersonId};db.Add(donor);a.Audit(tenant,"finance.donor.created",donor.Id);await db.SaveChangesAsync();return Results.Ok(donor);});
 t.MapGet("/contributions",async(Guid tenant,Guid? entity,string? kind,FinanceService s)=>{var q=s.Scoped<FinanceContribution>(tenant,entity:entity);if(kind!=null)q=q.Where(c=>c.Kind==kind);return await q.OrderByDescending(c=>c.Date).Take(200).ToListAsync();});
 t.MapPost("/contributions",async(Guid tenant,FinanceContribution r,AppDb db,Access a,FinanceService s)=>{var e=await s.Require(tenant,r.EntityId,r.UnitId,"finance.collect");FinanceService.Money(r.Pledged,e.Currency);if(r.Kind is not("Donation" or "Sponsorship")||r.Purpose.Length is <3 or >1000||!await db.Set<FinanceDonor>().AnyAsync(d=>d.TenantId==tenant&&d.EntityId==e.Id&&d.Id==r.DonorId&&d.UnitId==r.UnitId))throw new DomainException("Choose an authorized donor, purpose and contribution type");var contribution=new FinanceContribution{TenantId=tenant,EntityId=e.Id,UnitId=r.UnitId,DonorId=r.DonorId,Kind=r.Kind,Purpose=r.Purpose,Pledged=r.Pledged,Currency=e.Currency,Date=r.Date,DueOn=r.DueOn,Restricted=r.Restricted,AuthorId=a.UserId};db.Add(contribution);a.Audit(tenant,"finance.contribution.pledged",contribution.Id);await db.SaveChangesAsync();return Results.Ok(contribution);});
 t.MapPost("/contributions/{id:guid}/invoice",async(Guid tenant,Guid id,AppDb db,FinanceService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var c=await db.Set<FinanceContribution>().SingleOrDefaultAsync(c=>c.TenantId==tenant&&c.Id==id)??throw new AccessDeniedException();await s.Require(tenant,c.EntityId,c.UnitId,"finance.invoice");if(c.InvoiceId!=null)return Results.Ok(new{id=c.InvoiceId});var donor=await db.Set<FinanceDonor>().SingleAsync(d=>d.Id==c.DonorId);var invoice=await s.CreateInvoice(tenant,new(c.EntityId,c.UnitId!.Value,donor.Name,c.Date,c.DueOn,[new(c.Purpose,1,c.Pledged,0,0,c.Kind=="Donation"?"4300":"4400")],DonorId:c.DonorId,Purpose:c.Kind,Notes:"Contribution commitment. No tax-deductibility representation.",Submit:true));c.InvoiceId=invoice.Id;c.Status="Invoiced";await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(InvoiceDto(invoice));});
 t.MapPost("/expenses/{id:guid}/attachments",async(Guid tenant,Guid id,HttpRequest request,AppDb db,Access a,FinanceService s,IObjectStore store)=>{var x=await db.Set<FinanceExpense>().SingleOrDefaultAsync(x=>x.TenantId==tenant&&x.Id==id)??throw new AccessDeniedException();await s.Require(tenant,x.EntityId,x.UnitId,"finance.expense");if(x.Status!="Pending Approval"||x.AuthorId!=a.UserId||request.ContentLength is null or >2097152)throw new DomainException("Only the claimant can attach up to 2 MB evidence before approval");if(await db.Set<FinanceFile>().CountAsync(f=>f.TenantId==tenant&&f.ResourceId==id)>=5)throw new DomainException("Attach up to five evidence files");using var output=new MemoryStream();await request.Body.CopyToAsync(output);var bytes=output.ToArray();var type=request.ContentType?.Split(';')[0];if(type=="image/png")bytes=AssetEndpoints.SanitizePng(bytes);else if(type!="application/pdf"||bytes.Length<12||!Encoding.ASCII.GetString(bytes.Take(5).ToArray()).StartsWith("%PDF-")||!Encoding.ASCII.GetString(bytes.TakeLast(1024).ToArray()).Contains("%%EOF"))throw new DomainException("Use PNG or PDF evidence");var file=new FinanceFile{TenantId=tenant,EntityId=x.EntityId,UnitId=x.UnitId,ResourceId=id,Kind="Expense",AuthorId=a.UserId,Name=Path.GetFileName(request.Headers["X-Filename"].ToString())[..Math.Min(160,Path.GetFileName(request.Headers["X-Filename"].ToString()).Length)],ContentType=type,Length=bytes.Length};await store.Put(tenant,file.Id,bytes);db.Add(file);a.Audit(tenant,"finance.expense.evidence",id);await db.SaveChangesAsync();return Results.Ok(new{file.Id,file.Name});});
 t.MapGet("/files/{id:guid}",async(Guid tenant,Guid id,AppDb db,Access a,FinanceService s,IObjectStore store)=>{var file=await db.Set<FinanceFile>().SingleOrDefaultAsync(f=>f.TenantId==tenant&&f.Id==id)??throw new AccessDeniedException();await s.Require(tenant,file.EntityId,file.UnitId);if(file.Kind=="Report"){if(file.AuthorId!=a.UserId)throw new AccessDeniedException();await s.Require(tenant,file.EntityId,file.UnitId,"finance.export");var job=await db.Set<FinanceJob>().SingleAsync(j=>j.Id==file.ResourceId&&j.TenantId==tenant);var report=JsonSerializer.Deserialize<ReportJob>(job.Payload)!;if(report.Report=="Reconciliation")await s.Require(tenant,file.EntityId,file.UnitId,"finance.reconcile");}if(file.Kind=="Expense"&&!await a.Can(tenant,"finance.expense",file.UnitId)&&!await a.Can(tenant,"finance.approve",file.UnitId))throw new AccessDeniedException();return Results.File(store.Open(tenant,id),file.ContentType,Path.ChangeExtension(string.IsNullOrEmpty(file.Name)?"evidence":file.Name,file.ContentType=="image/png"?".png":".pdf"));});
 }
 static async Task ValidateFinanceLinks(Guid tenant,Guid? unit,Guid? eventId,Guid? committee,AppDb db,Access a){if(eventId!=null&&!await db.Set<CommunityEvent>().AnyAsync(e=>e.TenantId==tenant&&e.Id==eventId&&e.UnitId==unit))throw new AccessDeniedException();if(committee!=null&&!await db.Committees.AnyAsync(c=>c.TenantId==tenant&&c.Id==committee&&c.UnitId==unit))throw new AccessDeniedException();await Task.CompletedTask;}
}
public record BudgetInput(string AccountCode,decimal Amount);
public record BudgetChange(decimal Amount,string Lines,string Reason,int Revision);
public record ExpensePay(string Reference,DateOnly Date,string Method="Bank transfer",Guid? BankId=null);
public record BankWrite(Guid EntityId,Guid UnitId,string Name,string Details,string AccountCode="1010");
public record BankRow(DateOnly Date,string Reference,decimal Amount,string Description="");
public record BankImport(string Key,BankRow[] Rows);
public record ReconcileWrite(Guid PaymentId);
